class Solution:

    def findAnagrams(self, s, p):
        remaining = Counter(p)
        answer = []
        left = 0
        for right, char in enumerate(s):
            remaining[char] -= 1
            while remaining[char] < 0:
                remaining[s[left]] += 1
                left += 1
            if right - left + 1 == len(p):
                answer.append(left)
        return answer

class Solution:

    def subarraySum(self, nums, k):
        counts = {0: 1}
        prefix = answer = 0
        for value in nums:
            prefix += value
            answer += counts.get(prefix - k, 0)
            counts[prefix] = counts.get(prefix, 0) + 1
        return answer

