class Solution:

    def maxSlidingWindow(self, nums, k):
        candidates = deque()
        answer = []
        for i, value in enumerate(nums):
            while candidates and nums[candidates[-1]] <= value:
                candidates.pop()
            candidates.append(i)
            if candidates[0] <= i - k:
                candidates.popleft()
            if i >= k - 1:
                answer.append(nums[candidates[0]])
        return answer

