class Solution:

    def rotate(self, nums, k):
        n = len(nums)
        k %= n

        def reverse(left, right):
            while left < right:
                nums[left], nums[right] = (nums[right], nums[left])
                left += 1
                right -= 1
        reverse(0, n - 1)
        reverse(0, k - 1)
        reverse(k, n - 1)

class Solution:

    def productExceptSelf(self, nums):
        answer = [1] * len(nums)
        suffix = 1
        for i in range(len(nums) - 1, -1, -1):
            answer[i] = suffix
            suffix *= nums[i]
        prefix = 1
