class Solution:

    def reverseKGroup(self, head, k):
        dummy = ListNode(0, head)
        before = dummy
        while True:
            last = before
            for _ in range(k):
                last = last.next
                if last is None:
                    return dummy.next
            following = last.next
            first = before.next
            previous, current = (following, first)
            while current is not following:
                nxt = current.next
                current.next = previous
                previous, current = (current, nxt)
            before.next = last
            before = first

class Solution:

    def sortList(self, head):
        length = 0
        current = head
        while current:
            length += 1
            current = current.next

        def split(start, size):
            if start is None:
                return None
            for _ in range(size - 1):
                if start.next is None:
                    break
                start = start.next
            rest = start.next
            start.next = None
            return rest
        dummy = ListNode(0, head)
        width = 1
        while width < length:
            before = dummy
            current = dummy.next
            while current:
                left = current
                right = split(left, width)
                current = split(right, width)
                while left and right:
                    if left.val <= right.val:
                        before.next, left = (left, left.next)
                    else:
                        before.next, right = (right, right.next)
                    before = before.next
                before.next = left or right
                while before.next:
                    before = before.next
                before.next = current
            width *= 2
        return dummy.next

import heapq

class Solution:

    def mergeKLists(self, lists):
        heap = []
        for index, node in enumerate(lists):
            if node:
                heap.append((node.val, index, node))
        heapq.heapify(heap)
        dummy = ListNode()
        tail = dummy
        while heap:
            _, index, node = heapq.heappop(heap)
            following = node.next
            tail.next = node
            tail = node
            if following:
                heapq.heappush(heap, (following.val, index, following))
        tail.next = None
        return dummy.next

class _CacheNode:

    def __init__(self, key=0, value=0):
        self.key, self.value = (key, value)
