class LRUCache:

    def __init__(self, capacity):
        self.capacity = capacity
        self.items = {}
        self.head, self.tail = (_CacheNode(), _CacheNode())
        self.head.next = self.tail
        self.tail.prev = self.head

    def _remove(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev

    def _front(self, node):
        node.prev, node.next = (self.head, self.head.next)
        self.head.next.prev = node
        self.head.next = node

    def get(self, key):
        if key not in self.items:
            return -1
        node = self.items[key]
        self._remove(node)
        self._front(node)
        return node.value

    def put(self, key, value):
        if key in self.items:
            node = self.items[key]
            node.value = value
            self._remove(node)
        else:
            node = _CacheNode(key, value)
            self.items[key] = node
        self._front(node)
        if len(self.items) > self.capacity:
            expired = self.tail.prev
            self._remove(expired)
            del self.items[expired.key]

class Solution:

    def inorderTraversal(self, root):
        answer = []
        current = root
        while current:
            if current.left is None:
                answer.append(current.val)
                current = current.right
                continue
            previous = current.left
            while previous.right and previous.right is not current:
                previous = previous.right
            if previous.right is None:
                previous.right = current
                current = current.left
            else:
                previous.right = None
                answer.append(current.val)
                current = current.right
        return answer

