class Solution:

    def levelOrder(self, root):
        if root is None:
            return []
        queue = deque([root])
        answer = []
        while queue:
            layer = []
            for _ in range(len(queue)):
                node = queue.popleft()
                layer.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            answer.append(layer)
        return answer

class Solution:

    def sortedArrayToBST(self, nums):

        def build(left, right):
            if left == right:
                return None
            middle = (left + right) // 2
            node = TreeNode(nums[middle])
