class Solution:

    def kthSmallest(self, root, k):
        remaining = k

        def visit(node):
            nonlocal remaining
            if node is None:
                return None
            found = visit(node.left)
            if found is not None:
                return found
            remaining -= 1
            if remaining == 0:
                return node.val
            return visit(node.right)
        return visit(root)

