class Solution:

    def maxPathSum(self, root):
        best = float('-inf')

        def chain(node):
            nonlocal best
            if node is None:
                return 0
            left = max(0, chain(node.left))
            right = max(0, chain(node.right))
            best = max(best, node.val + left + right)
            return node.val + max(left, right)
        chain(root)
        return best

class Solution:

    def numIslands(self, grid):
        rows, cols = (len(grid), len(grid[0]))

        def search(row, col):
            if not 0 <= row < rows or not 0 <= col < cols:
                return
            if grid[row][col] != '1':
                return
            grid[row][col] = '2'
            search(row, col - 1)
            search(row, col + 1)
            search(row - 1, col)
            search(row + 1, col)
        answer = 0
        for row in range(rows):
            for col in range(cols):
                if grid[row][col] == '1':
                    search(row, col)
                    answer += 1
        return answer

class Solution:

    def orangesRotting(self, grid):
        rows, cols = (len(grid), len(grid[0]))
        fresh = 0
        frontier = []
        for row in range(rows):
            for col in range(cols):
                if grid[row][col] == 1:
                    fresh += 1
                elif grid[row][col] == 2:
                    frontier.append((row, col))
        minutes = 0
        while frontier and fresh:
            minutes += 1
            current_layer = frontier
            frontier = []
            for row, col in current_layer:
                for next_row, next_col in ((row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)):
                    if 0 <= next_row < rows and 0 <= next_col < cols and (grid[next_row][next_col] == 1):
                        grid[next_row][next_col] = 2
                        fresh -= 1
                        frontier.append((next_row, next_col))
        return minutes if fresh == 0 else -1

class Solution:

    def canFinish(self, numCourses, prerequisites):
        graph = [[] for _ in range(numCourses)]
        for course, previous in prerequisites:
            graph[previous].append(course)
        color = [0] * numCourses

        def visit(course):
            if color[course] == 1:
                return False
            if color[course] == 2:
                return True
            color[course] = 1
            for following in graph[course]:
                if not visit(following):
                    return False
            color[course] = 2
            return True
        return all((visit(course) for course in range(numCourses)))

class Trie:

    def __init__(self):
        self.children = {}
        self.is_word = False

    def insert(self, word):
        node = self
        for char in word:
            if char not in node.children:
                node.children[char] = Trie()
            node = node.children[char]
        node.is_word = True

    def _walk(self, text):
        node = self
        for char in text:
            if char not in node.children:
                return None
            node = node.children[char]
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.is_word

    def startsWith(self, prefix):
        return self._walk(prefix) is not None

class Solution:

    def permute(self, nums):
        size = len(nums)
        path = [0] * size
        used = [False] * size
        answer = []

        def search(position):
            if position == size:
                answer.append(path.copy())
                return
            for index in range(size):
                if not used[index]:
                    path[position] = nums[index]
                    used[index] = True
                    search(position + 1)
                    used[index] = False
        search(0)
        return answer

DIGIT_LETTERS = ('', '', 'abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz')

class Solution:

    def letterCombinations(self, digits):
        size = len(digits)
        if size == 0:
            return []
        path = [''] * size
        answer = []

        def search(position):
            if position == size:
                answer.append(''.join(path))
                return
            for letter in DIGIT_LETTERS[int(digits[position])]:
                path[position] = letter
                search(position + 1)
        search(0)
        return answer

class Solution:

    def combinationSum(self, candidates, target):
        n = len(candidates)
        possible = [[False] * (target + 1) for _ in range(n + 1)]
        possible[0][0] = True
        for i, coin in enumerate(candidates):
            for amount in range(target + 1):
                possible[i + 1][amount] = possible[i][amount] or (amount >= coin and possible[i + 1][amount - coin])
        answer = []
        path = []

        def search(i, remaining):
            if remaining == 0:
                answer.append(path.copy())
                return
            if i < 0 or not possible[i + 1][remaining]:
                return
            search(i - 1, remaining)
            coin = candidates[i]
            if remaining >= coin:
                path.append(coin)
                search(i, remaining - coin)
                path.pop()
        search(n - 1, target)
        return answer

class Solution:

    def generateParenthesis(self, n):
        path = [''] * (2 * n)
        answer = []

        def search(left_count, right_count):
            if right_count == n:
                answer.append(''.join(path))
                return
            position = left_count + right_count
            if left_count < n:
                path[position] = '('
                search(left_count + 1, right_count)
            if right_count < left_count:
                path[position] = ')'
                search(left_count, right_count + 1)
        search(0, 0)
        return answer

class Solution:

    def exist(self, board, word):
        rows, cols = (len(board), len(board[0]))

        def search(row, col, position):
            if board[row][col] != word[position]:
                return False
            if position == len(word) - 1:
                return True
            board[row][col] = ''
            for next_row, next_col in ((row, col - 1), (row, col + 1), (row - 1, col), (row + 1, col)):
                if 0 <= next_row < rows and 0 <= next_col < cols and search(next_row, next_col, position + 1):
                    return True
            board[row][col] = word[position]
            return False
        return any((search(row, col, 0) for row in range(rows) for col in range(cols)))

