                path.append(piece)
                search(end)
                path.pop()
        search(0)
        return answer

class Solution:

    def searchInsert(self, nums, target):
        left, right = (0, len(nums))
        while left < right:
            middle = (left + right) // 2
            if nums[middle] < target:
                left = middle + 1
            else:
