class Solution:

    def searchMatrix(self, matrix, target):
        rows, cols = (len(matrix), len(matrix[0]))
        left, right = (-1, rows * cols)
        while left + 1 < right:
            middle = (left + right) // 2
            value = matrix[middle // cols][middle % cols]
            if value == target:
                return True
            if value < target:
                left = middle
            else:
                right = middle
        return False

class Solution:

    def searchRange(self, nums, target):

        def boundary(strict):
            left, right = (0, len(nums))
            while left < right:
                middle = (left + right) // 2
                if nums[middle] < target or (strict and nums[middle] == target):
                    left = middle + 1
                else:
                    right = middle
            return left
        first = boundary(False)
        if first == len(nums) or nums[first] != target:
            return [-1, -1]
        return [first, boundary(True) - 1]

class Solution:

    def search(self, nums, target):
        left, right = (0, len(nums) - 1)
        last = nums[-1]
        while left <= right:
            middle = (left + right) // 2
            value = nums[middle]
            if value == target:
                return middle
            if (value > last) == (target > last):
                move_right = value < target
            else:
                move_right = value > last
            if move_right:
                left = middle + 1
            else:
                right = middle - 1
        return -1

